/**
 * Measures chunk promotion's main-thread CPU and throughput with terrain generated by workers.
 *
 * `join` promotes one burst of nearby chunks. `steady` promotes four smaller batches at separate
 * positions so the generator cannot return a cached chunk from an earlier sample. The measured
 * thread CPU excludes the workers and the digest makes the same workload comparable before and
 * after moving biome packing.
 *
 * Run `pnpm --filter @jsprismarine/prismarine run bench:biome-promotion [workers] [samples]`.
 * This needs Mojang's Java world generation data, the same as the generator does.
 */
import { createHash } from 'node:crypto';
import os, { availableParallelism } from 'node:os';

import { DataDrivenGenerator, defaultTerrainPipeline } from '../src/world/generators/datadriven/DataDrivenGenerator';
import {
    findJavaWorldgenSources,
    loadJavaWorldgenRegistries
} from '../src/world/generators/datadriven/javaWorldgenData';
import { percentile } from './percentile';

const workers = Number.parseInt(process.argv[2] ?? '4', 10);
const sampleCount = Number.parseInt(process.argv[3] ?? '3', 10);
const seed = 1234n;
const joinChunks = 16;
const steadyBatch = 4;
const steadyRounds = 4;

if (![workers, sampleCount].every(Number.isSafeInteger) || workers < 1 || sampleCount < 1) {
    throw new RangeError('Workers and sample count must be positive integers');
}

const sources = findJavaWorldgenSources();
if (sources === undefined) {
    process.stderr.write(
        'No Java world generation data. Run `pnpm --filter @jsprismarine/bedrock-data run fetch:sources` ' +
            'and `pnpm --filter @jsprismarine/bedrock-data run datagen:java` first.\n'
    );
    process.exit(1);
}

const registries = loadJavaWorldgenRegistries(sources);
let workerUnavailable: string | undefined;
const generator = new DataDrivenGenerator({
    registries,
    carve: false,
    decorate: false,
    structures: false,
    terrain: {
        pipeline: defaultTerrainPipeline(),
        workers,
        onUnavailable: (reason) => {
            workerUnavailable = reason;
            process.stderr.write(`no terrain workers: ${reason}\n`);
        }
    }
});

interface Sample {
    readonly wallMs: number;
    readonly mainThreadCpuMs: number;
    readonly chunks: number;
    readonly digest: string;
}

/** A compact square whose chunks are all distinct from previous workload samples. */
const positions = (count: number, baseX: number): readonly (readonly [number, number])[] => {
    const side = Math.ceil(Math.sqrt(count));
    return Array.from(
        { length: count },
        (_unused, index) => [baseX + (index % side), Math.trunc(index / side)] as const
    );
};

/** Builds one burst of chunks and hashes them in request order after timing. */
const sample = async (count: number, baseX: number, batches: number): Promise<Sample> => {
    const hash = createHash('sha256');
    const started = performance.now();
    const cpuBefore = process.threadCpuUsage();

    if (batches === 1) {
        const generated = await Promise.all(
            positions(count, baseX).map(async ([x, z]) => ({ x, z, chunk: await generator.generateChunk(x, z, seed) }))
        );
        const wallMs = performance.now() - started;
        const cpu = process.threadCpuUsage(cpuBefore);
        for (const { x, z, chunk } of generated) {
            hash.update(`${x},${z}\0`);
            hash.update(chunk.networkSerialize());
        }
        return {
            wallMs,
            mainThreadCpuMs: (cpu.user + cpu.system) / 1000,
            chunks: generated.length,
            digest: hash.digest('hex')
        };
    }

    const allGenerated: {
        readonly x: number;
        readonly z: number;
        readonly chunk: Awaited<ReturnType<typeof generator.generateChunk>>;
    }[] = [];
    for (let batch = 0; batch < batches; batch++) {
        const generated = await Promise.all(
            positions(count / batches, baseX + batch * 8).map(async ([x, z]) => ({
                x,
                z,
                chunk: await generator.generateChunk(x, z, seed)
            }))
        );
        allGenerated.push(...generated);
    }

    const cpu = process.threadCpuUsage(cpuBefore);
    const wallMs = performance.now() - started;
    for (const { x, z, chunk } of allGenerated) {
        hash.update(`${x},${z}\0`);
        hash.update(chunk.networkSerialize());
    }
    return {
        wallMs,
        mainThreadCpuMs: (cpu.user + cpu.system) / 1000,
        chunks: allGenerated.length,
        digest: hash.digest('hex')
    };
};

/** Summarizes one workload's wall time, main-thread CPU, and promotion throughput. */
const summary = (name: string, samples: readonly Sample[]) => {
    const wall = samples.map(({ wallMs }) => wallMs).sort((left, right) => left - right);
    const cpu = samples.map(({ mainThreadCpuMs }) => mainThreadCpuMs).sort((left, right) => left - right);
    const digests = createHash('sha256')
        .update(samples.map(({ digest }) => digest).join('\n'))
        .digest('hex');
    const p50Wall = percentile(wall, 0.5);
    return {
        workload: name,
        chunksPerSample: samples[0]?.chunks ?? 0,
        wallP50Ms: p50Wall,
        mainThreadCpuP50Ms: percentile(cpu, 0.5),
        chunksPerSecond: ((samples[0]?.chunks ?? 0) / p50Wall) * 1000,
        outputDigest: digests
    };
};

let nextBaseX = 0;
const run = async (name: 'join' | 'steady'): Promise<Sample> => {
    const baseX = nextBaseX;
    nextBaseX += 64;
    return name === 'join' ? sample(joinChunks, baseX, 1) : sample(steadyBatch * steadyRounds, baseX, steadyRounds);
};

try {
    await run('join');
    await run('steady');

    const joinSamples: Sample[] = [];
    const steadySamples: Sample[] = [];
    for (let repetition = 0; repetition < sampleCount; repetition++) {
        joinSamples.push(await run('join'));
        steadySamples.push(await run('steady'));
    }

    process.stdout.write(
        `${JSON.stringify({
            benchmark: 'biome-promotion',
            seed: seed.toString(),
            node: process.version,
            platform: `${os.platform()}-${os.arch()}`,
            cpu: os.cpus()[0]?.model ?? 'unknown',
            availableParallelism: availableParallelism(),
            workerCount: workerUnavailable === undefined ? workers : 0,
            warmups: 2,
            samples: sampleCount,
            workloads: [summary('join', joinSamples), summary('steady', steadySamples)]
        })}\n`
    );
} finally {
    generator.stopGenerating();
}
